<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory Studio</title>
<style>
:root{font-family:system-ui;color:#17243a;background:#f2f5fa}body{margin:0}main{max-width:1050px;margin:50px auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center}h1{font-size:36px;margin-bottom:8px}p{color:#526278}.card{background:white;padding:24px;border-radius:16px;margin-top:20px;box-shadow:0 5px 25px #142d5010}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}label{display:block;font-weight:600}input,textarea,button{font:inherit;border-radius:8px;padding:10px;border:1px solid #bdc9d9;box-sizing:border-box}input,textarea{width:100%;margin:7px 0 14px}button{cursor:pointer;background:#233c8b;color:white}button.secondary{background:white;color:#233c8b}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:14px;border-bottom:1px solid #e3e9f2}#status{white-space:pre-wrap}nav{display:flex;gap:12px;align-items:center;margin-top:16px}.table-wrap{overflow:auto}@media(max-width:650px){.grid{grid-template-columns:1fr}main{margin:10px auto}header{display:block}}
</style></head><body><main><header><div><h1>Inventory Studio</h1><p>Manage products, pricing and stock in one workspace.</p></div><span>PRODUCT OPERATIONS</span></header>
<section class="card"><label for="token">Your access token</label><input type="password" id="token" autocomplete="off" placeholder="Paste your local demo token"><button id="connect">Connect</button><p>Token stays in memory for this page session.</p></section>
<section class="card"><h2 id="form-title">New product</h2><form id="product-form"><div class="grid"><div><label for="name">Name</label><input id="name" maxlength="160" required></div><div><label for="sku">SKU</label><input id="sku" pattern="[A-Z0-9_-]+" maxlength="64" required></div><div><label for="price_cents">Price (USD cents)</label><input id="price_cents" type="number" min="0" max="100000000" step="1" required></div><div><label for="stock">Stock</label><input id="stock" type="number" min="0" max="1000000" step="1" required></div></div><label for="description">Description</label><textarea id="description" maxlength="5000"></textarea><button id="save">Save product</button> <button type="button" class="secondary" id="cancel">Reset</button></form></section>
<section class="card"><h2>Products</h2><form id="search-form"><label for="search">Search name or SKU</label><input id="search"><button>Search</button></form><div class="table-wrap"><table><thead><tr><th>Name</th><th>SKU</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody id="rows"></tbody></table></div><nav><button id="prev">Previous</button><span id="page-info"></span><button id="next">Next</button></nav></section><p id="status" role="status" aria-live="polite"></p></main>
<script>
const $=id=>document.getElementById(id);let token='',editing=null,page=1,lastPage=1,query='';
function status(message){$('status').textContent=message;}
async function api(path,method='GET',body){const r=await fetch('/api/v1/'+path,{method,headers:{Accept:'application/json',Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const data=r.status===204?null:await r.json();if(!r.ok)throw Error(data?.errors?Object.values(data.errors).flat().join('\n'):data?.message||'Request failed');return data;}
function reset(){editing=null;$('product-form').reset();$('form-title').textContent='New product';}
async function load(){try{const result=await api('products?'+new URLSearchParams({page,per_page:10,q:query}));lastPage=result.meta.last_page;$('rows').replaceChildren();for(const p of result.data){const row=document.createElement('tr');for(const value of [p.name,p.sku,new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(p.price_cents/100),p.stock]){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}const actions=document.createElement('td');const edit=document.createElement('button');edit.textContent='Edit';edit.onclick=()=>{editing=p.id;for(const key of ['name','sku','price_cents','stock','description'])$(key).value=p[key]??'';$('form-title').textContent='Edit product';$('name').focus();};const del=document.createElement('button');del.textContent='Delete';del.className='secondary';del.onclick=async()=>{if(!confirm('Delete '+p.name+'?'))return;del.disabled=true;try{await api('products/'+p.id,'DELETE');if(editing===p.id)reset();page=1;await load();status('Product deleted.');}catch(e){status(e.message);}finally{del.disabled=false;}};actions.append(edit,document.createTextNode(' '),del);row.append(actions);$('rows').append(row);}$('page-info').textContent=`Page ${result.meta.current_page} of ${lastPage} · ${result.meta.total} products`;$('prev').disabled=page<=1;$('next').disabled=page>=lastPage;}catch(e){status(e.message);}}
$('connect').onclick=()=>{token=$('token').value.trim();$('token').value='';page=1;status('');load();};
$('product-form').onsubmit=async e=>{e.preventDefault();$('save').disabled=true;const body={};for(const key of ['name','sku','description'])body[key]=$(key).value;for(const key of ['price_cents','stock'])body[key]=Number($(key).value);try{await api('products'+(editing?'/'+editing:''),editing?'PUT':'POST',body);reset();page=1;await load();status('Product saved.');}catch(e){status(e.message);}finally{$('save').disabled=false;}};
$('cancel').onclick=reset;$('search-form').onsubmit=e=>{e.preventDefault();query=$('search').value;page=1;load();};$('prev').onclick=()=>{if(page>1){page--;load();}};$('next').onclick=()=>{if(page<lastPage){page++;load();}};
</script></body></html>
